import java.util.HashMap;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

// Facade pattern: only get() and put() are public, everything else is
// hidden pointer surgery on the internal HashMap plus doubly linked list
public class LRUCache<K, V> {
    private final int capacity;
    private final Map<K, Node<K, V>> map;
    private final Node<K, V> head; // dummy head, head.next = most recently used
    private final Node<K, V> tail; // dummy tail, tail.prev = least recently used
    private final List<CacheEvictionListener<K, V>> listeners = new ArrayList<>();

    public LRUCache(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("capacity must be positive");
        }
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.head = new Node<>(null, null);
        this.tail = new Node<>(null, null);
        head.next = tail;
        tail.prev = head;
    }

    public void addEvictionListener(CacheEvictionListener<K, V> listener) {
        listeners.add(listener);
    }

    public V get(K key) {
        Node<K, V> node = map.get(key);
        if (node == null) return null;
        moveToFront(node);
        return node.value;
    }

    public void put(K key, V value) {
        if (map.containsKey(key)) {
            Node<K, V> node = map.get(key);
            node.value = value;
            moveToFront(node);
            return;
        }
        if (map.size() == capacity) {
            evictLeastRecentlyUsed();
        }
        Node<K, V> node = new Node<>(key, value);
        map.put(key, node);
        addToFront(node);
    }

    private void addToFront(Node<K, V> node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    private void remove(Node<K, V> node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void moveToFront(Node<K, V> node) {
        remove(node);
        addToFront(node);
    }

    private void evictLeastRecentlyUsed() {
        Node<K, V> lru = tail.prev;
        remove(lru);
        map.remove(lru.key);
        for (CacheEvictionListener<K, V> listener : listeners) {
            listener.onEvict(lru.key, lru.value);
        }
    }

    public int size() {
        return map.size();
    }
}

