int main() {
    LRUCache cache(2);
    PrintEvictionListener listener;
    cache.addEvictionListener(&listener);

    cache.put(1, "A");
    cache.put(2, "B");
    auto result1 = cache.get(1);
    cout << "get(1): " << (result1.has_value() ? *result1 : "null") << endl;
    cache.put(3, "C");
    auto result2 = cache.get(2);
    cout << "get(2): " << (result2.has_value() ? *result2 : "null") << endl;
    auto result3 = cache.get(3);
    cout << "get(3): " << (result3.has_value() ? *result3 : "null") << endl;

